/**
 * SVG markup for one glyph path, centered at (cx, cy) in a box of
 * `size` px, filled with `color`.
 * o: {outlineW} outline width in grid units (0 = no outline),
 *    {outlineO, fillO} opacities in [0,1] (default 1).
 */
export function glyphSVG(d, cx, cy, size, color, o = {}) {
  const ow = o.outlineW != null ? o.outlineW : 0;
  const oo = o.outlineO != null ? o.outlineO : 1;
  const fo = o.fillO != null ? o.fillO : 1;
  const k = size / 100;
  let attrs = `fill="${color}" fill-opacity="${fo}"`;
  if (ow > 0) {
    attrs += ` stroke="${color}" stroke-width="${ow}" stroke-opacity="${oo}"`
      + ' stroke-linejoin="round"';
  }
  return `<g class="svg-glyph" transform="translate(${cx.toFixed(1)} ${cy.toFixed(1)}) `
    + `scale(${k.toFixed(4)}) translate(-50 -50)"><path d="${d}" ${attrs}/></g>`;
}

/** Glyph markup for sign index i (0 = Aries). */
export function signGlyphSVG(i, cx, cy, size, color, o) {
  return glyphSVG(SIGN_PATHS[i], cx, cy, size, color, o);
}

/** Glyph markup for a point key ('sun', 'true-node', ...); '' if unknown. */
export function bodyGlyphSVG(key, cx, cy, size, color, o) {
  const d = BODY_PATHS[key];
  return d ? glyphSVG(d, cx, cy, size, color, o) : '';
}
